#[test]
fn implied_vol_recovers_the_true_volatility_deep_into_the_tails() {
    use quantkit::implied_vol::{solve_detailed, SolverConfig};
    use quantkit::{OptionParams, OptionType};
    let mut worst = 0.0_f64;
    for &(s, k, r, q, vol, t, is_call, price) in IV_REFS {
        let kind = if is_call {
            OptionType::Call
        } else {
            OptionType::Put
        };
        let c = OptionParams::builder()
            .spot(s)
            .strike(k)
            .rate(r)
            .dividend_yield(q)
            .expiry(t)
            .build_contract()
            .unwrap();
        let sol = solve_detailed(&c, kind, price, SolverConfig::default()).unwrap_or_else(|e| {
            panic!("s={s} k={k} vol={vol} t={t} call={is_call} price={price:e}: {e}")
        });
        let rel = (sol.vol - vol).abs() / vol;
        worst = worst.max(rel);
        assert!(
            rel < 2e-12,
            "k={k} vol={vol} t={t} call={is_call} price={price:e}: got {} (rel err {rel:e})",
            sol.vol
        );
    }
    assert!(IV_REFS.len() > 100);
    println!(
        "worst relative volatility error over {} cases: {worst:e}",
        IV_REFS.len()
    );
}

